/**
 * @method
 * @name scwin.titleChange
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.titleChange = function () {
    /* sdd-asis-lifecycle:begin titleChange — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const titleTp = '' + dma_pageContext.get("keyValue") + '';
    if (titleTp === "TBLD_O_SUBCOM_STAT") {
        $("#popup_title").text("자회사 선택");
    } else {
        if (titleTp === "TBLD_O_SUBSCOM_STAT") {
            $("#popup_title").text("종속회사 선택");
        } else {
            if (titleTp === "TBLD_O_OTHCORP_CONTRB_STAT") {
                $("#popup_title").text("타법인 선택");
            }
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.selectThis
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.selectThis = async function () {
    /* sdd-asis-lifecycle:begin selectThis — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.form || { elements: [] });
    if (($c.util.getComponent('dlt_comList').getTotalRow() > 0) != null) {
        if ($c.util.getComponent('dlt_comList').getTotalRow() > 1) {
            if (isChecked(($c.util.getComponent('dlt_comList').getTotalRow() > 0))) {
                frm.action = "disclosureCommon.do";
                await scwin.tx_selectThis();
            } else {
                await $c.win.alert("하나의 회사를 선택하시기 바랍니다.");
            }
        } else {
            if (($c.util.getComponent('dlt_comList').getTotalRow() > 0).checked === false) {
                await $c.win.alert("하나의 회사를 선택하시기 바랍니다.");
            } else {
                frm.action = "disclosureCommon.do";
                await scwin.tx_selectThis();
            }
        }
    } else {

    }
    function isChecked(ver) {
        let isOk = false;
        for (let i = 0; i < ver.length; i++) {
            if (ver[i].checked) {
                isOk = true;
            }
        }
        return isOk;
    }
    /* sdd-asis-lifecycle:end */
};


